import {ENTITY_TYPES,COLLECTIONS,PURPOSES,ATTRIBUTE_MODELS,entity,addReference,documentReferences,referenceKey,assetDocuments,assetObligations,assetTasks,requirementStatus,assetFields,adaptAssetFields,ensureInventory} from './inventory-model.js?v=17';
import {total,remaining} from './data.js?v=17';

export function createInventory(a){
  const {esc,btn,icon,pill,link,empty,panel,money,fullDate}=a;
  let activeAsset='',assetTab='overview',scopeCompany='',docContext='all',docState='all',docSearch='',docView='list',assetKind='all';
  const uid=p=>p+'-'+crypto.randomUUID();
  const owned=(type,id)=>a.scope(type).find(x=>x.id===id);
  function sync(){if(scopeCompany!==a.company){scopeCompany=a.company;activeAsset='';assetTab='overview';docContext='all';docSearch='';assetKind='all'}ensureInventory(a.state)}
  function setAsset(id){sync();const next=owned('assets',id)?id:'';if(activeAsset!==next)assetTab='overview';activeAsset=next}
  const refButton=r=>`<button type="button" class="reference-chip ${r.purpose}" ${r.kind==='company'?'data-go="companies"':`data-open="${r.kind}" data-id="${esc(r.id)}"`} title="${esc(r.via.join(' · '))}">${icon(r.kind==='obligation'?'wallet':r.kind==='company'?'company':r.kind==='asset'?'asset':'contract')}<span>${esc(r.label)}</span></button>`;
  function purposeTags(refs){const roles=[...new Set(refs.map(r=>r.purpose))];return roles.map(p=>pill(PURPOSES[p],p==='documentation'?'green':'blue')).join('')||pill('Referência a definir','amber')}
  function referencePanel(d,editable=true){const refs=documentReferences(a.state,d);return `<section class="document-references"><div class="reference-heading"><div><span class="eyebrow">Referências do documento</span><h3>A que este arquivo se refere?</h3></div>${editable?btn('Organizar referências',`data-open="document-references" data-id="${esc(d.id)}"`,'','link'):''}</div><div class="reference-purpose">${purposeTags(refs)}</div>${refs.length?`<div class="reference-detail-list">${refs.map(r=>`<div><div>${refButton(r)}${pill(ENTITY_TYPES[r.kind])}${pill(r.direct?'Vínculo direto':'Contexto relacionado',r.direct?'':'blue')}</div><small>${esc(r.via.join(' · '))}</small>${r.notes.map(n=>`<p>${esc(n)}</p>`).join('')}</div>`).join('')}</div>`:empty('Referência ainda não definida','Indique a empresa, ativo, contrato ou obrigação que este documento atende.')}<p class="reference-footnote">O mesmo original pode servir a mais de um contexto. Um documento de operação relacionado ao ativo não substitui sua documentação cadastral.</p></section>`}
  function documents(){sync();const all=a.scope('documents').map(d=>({d,refs:documentReferences(a.state,d)}));
    const matches=(row,filter)=>filter==='all'||(filter==='unlinked'?!row.refs.length:filter==='company'?row.refs.some(r=>r.kind==='company'&&r.purpose==='documentation'):filter==='asset'?row.refs.some(r=>r.kind==='asset'&&r.purpose==='documentation'):filter==='contract'?row.refs.some(r=>r.kind==='contract'&&r.purpose==='documentation'):row.refs.some(r=>r.purpose==='support'));
    const rows=all.filter(row=>matches(row,docContext)&&(docState==='all'||(docState==='reviewed'?row.d.status==='Revisado':row.d.status!=='Revisado'))&&[row.d.name,row.d.type,row.d.source,...row.refs.map(r=>r.label)].join(' ').toLocaleLowerCase('pt-BR').includes(docSearch.toLocaleLowerCase('pt-BR')));
    const contexts=[['all','Todo o acervo','file'],['company','Documentação da empresa','company'],['asset','Documentação de ativos','asset'],['operation','Documentos de operações','wallet'],['unlinked','Sem referência','link']];
    return a.titleBlock('Documentos','O original em um só lugar. Suas referências, sempre visíveis.',btn('Enviar documento','data-open="newdoc"','primary','plus'),'Acervo em contexto')+`<div class="reference-filters">${contexts.map(([id,label,ico])=>`<button data-reference-filter="${id}" class="${docContext===id?'active':''}" aria-pressed="${docContext===id}">${icon(ico)}<strong>${all.filter(r=>matches(r,id)).length}</strong><span>${label}</span></button>`).join('')}</div><div class="inventory-toolbar"><label class="inventory-search">${icon('search')}<input type="search" aria-label="Buscar documento ou referência" placeholder="Buscar documento, ativo ou referência" value="${esc(docSearch)}" data-inventory-search></label><select aria-label="Conferência dos documentos" data-inventory-state><option value="all" ${docState==='all'?'selected':''}>Todas as situações</option><option value="pending" ${docState==='pending'?'selected':''}>Precisam de ação</option><option value="reviewed" ${docState==='reviewed'?'selected':''}>Conferidos</option></select><div class="segments" aria-label="Visualização dos documentos">${[['list','Lista'],['cards','Cartões']].map(([id,label])=>`<button data-inventory-view="${id}" class="${docView===id?'active':''}" aria-pressed="${docView===id}">${label}</button>`).join('')}</div></div><div class="inventory-caption"><span>${rows.length} documentos nesta seleção</span><span>As categorias podem compartilhar o mesmo documento.</span></div>${!rows.length?empty('Nenhum documento nesta seleção','Altere os filtros ou envie um documento.'):docView==='list'?`<section class="panel document-reference-table"><div class="table-wrap"><table><thead><tr><th>Documento / origem</th><th>Finalidade</th><th>Referências</th><th>Conferência</th><th></th></tr></thead><tbody>${rows.map(({d,refs})=>`<tr><td><button class="document-name" data-open="document" data-id="${esc(d.id)}">${icon(d.locked?'lock':'file')}<span><strong>${esc(d.name)}</strong><small>${esc(d.type)} · ${fullDate(d.date)}<br>${esc(d.source)}</small></span></button></td><td><div class="purpose-stack">${purposeTags(refs)}</div></td><td><div class="reference-chips">${refs.slice(0,2).map(refButton).join('')}${refs.length>2?`<button class="textbtn" data-open="document-references" data-id="${esc(d.id)}">+ ${refs.length-2} referências</button>`:''}${!refs.length?'<span class="annotation">A organizar</span>':''}</div></td><td>${pill(d.status,d.status==='Revisado'?'green':'amber')}</td><td><button class="iconbtn" data-open="document-references" data-id="${esc(d.id)}" aria-label="Organizar referências de ${esc(d.name)}">${icon('link')}</button></td></tr>`).join('')}</tbody></table></div></section>`:`<div class="reference-document-grid">${rows.map(({d,refs})=>`<article class="reference-document-card"><button class="document-name" data-open="document" data-id="${esc(d.id)}">${icon(d.locked?'lock':'file')}<span><strong>${esc(d.name)}</strong><small>${esc(d.type)} · ${fullDate(d.date)}</small></span></button><div class="reference-purpose">${purposeTags(refs)}</div><div class="reference-chips">${refs.slice(0,2).map(refButton).join('')}</div><div class="reference-card-bottom">${pill(d.status,d.status==='Revisado'?'green':'amber')}${btn('Referências',`data-open="document-references" data-id="${esc(d.id)}"`)}</div></article>`).join('')}</div>`}`;
  }
  function inventory(){sync();const asset=owned('assets',activeAsset);if(asset)return profile(asset);
    const assets=a.scope('assets').filter(x=>assetKind==='all'||x.kind===assetKind);
    return a.titleBlock('Ativos','Cada ativo, com sua identidade, documentação e vida financeira.',btn('Cadastrar ativo','data-open="newasset"','primary','plus'),'Inventário da empresa')+`<div class="inventory-toolbar"><div class="segments" aria-label="Tipo de ativo">${['all',...new Set(a.scope('assets').map(x=>x.kind))].map(k=>`<button data-inventory-kind="${esc(k)}" class="${assetKind===k?'active':''}" aria-pressed="${assetKind===k}">${k==='all'?'Todos':esc(k)}</button>`).join('')}</div><span class="annotation">${assets.length} ativos · ${esc(a.get('companies',a.company).name)}</span></div><div class="inventory-asset-grid">${assets.map(x=>{const docs=assetDocuments(a.state,x),pending=x.dossier.requirements.filter(r=>requirementStatus(a.state,r,a.NOW).tone!=='green').length;return `<article class="inventory-asset-card"><div class="asset-card-top"><span class="asset-icon">${icon(x.kind==='Veículo'?'car':'asset')}</span>${pill(x.status)}</div><span class="eyebrow">${esc(x.kind)} · ${esc(x.relationship)}</span><h2>${esc(x.name)}</h2><p>${esc(x.description||'Complete as características deste ativo.')}</p><div class="asset-facts"><span><b>${docs.length}</b> documentos</span><span><b>${assetTasks(a.state,x).filter(t=>!t.done).length}</b> tarefas</span></div><div class="asset-card-bottom">${pill(pending?`${pending} item(ns) a conferir`:x.dossier.requirements.length?'Lista documental conferida':'Lista documental a definir',pending?'amber':'')}${btn('Abrir ativo',`data-asset-page="${esc(x.id)}"`,'','chevron')}</div></article>`}).join('')||empty('Cadastre seu primeiro ativo','Escolha o tipo e adapte as características à sua operação.')}</div><p class="reference-footnote">As listas de documentação são definidas por você. Um vínculo cadastrado não substitui a conferência do conteúdo.</p>`;
  }
  function profile(x,drawer=false){const docs=assetDocuments(a.state,x),tasks=assetTasks(a.state,x),requirements=x.dossier.requirements;
    return `${!drawer?'<button class="textbtn inventory-back" data-assets-list>← Todos os ativos</button>':''}<div class="asset-profile-hero"><div class="asset-profile-icon">${icon(x.kind==='Veículo'?'car':'asset')}</div><div><span class="eyebrow">${esc(x.kind)} · ${esc(a.get('companies',x.company).name)}</span><h1>${esc(x.name)}</h1><p>${esc(x.description)}</p><div class="profile-tags">${pill(x.relationship)}${pill(x.status)}</div></div><div class="asset-profile-actions">${btn('Editar características',`data-open="asset-edit" data-id="${esc(x.id)}"`,'primary','asset')}${drawer?btn('Abrir painel completo',`data-asset-page="${esc(x.id)}"`):''}</div></div><div class="profile-tabs" aria-label="Seções do ativo">${[['overview','Características'],['documents',`Documentação · ${docs.length}`],['finance','Movimentações'],['tasks',`Tarefas · ${tasks.filter(t=>!t.done).length}`]].map(([id,label])=>`<button data-asset-tab="${id}" class="${assetTab===id?'active':''}" aria-pressed="${assetTab===id}">${label}</button>`).join('')}</div>${assetTab==='documents'?assetDocumentation(x):assetTab==='finance'?assetFinance(x):assetTab==='tasks'?assetTaskList(x):`<div class="asset-overview-grid">${panel('Características do ativo','Campos que acompanham a natureza deste bem.',`<dl class="profile-fields">${x.dossier.attributes.map(f=>`<div><dt>${esc(f.label)}</dt><dd>${esc(f.value||'A informar')}</dd></div>`).join('')||'<div><dt>Características</dt><dd>Adicione os campos relevantes.</dd></div>'}</dl>`)}<div>${panel('Contexto e particularidades','O que precisa acompanhar este ativo.',`<div class="profile-purpose"><p>${esc(x.details||'Registre condições de uso, responsabilidades ou particularidades do ativo.')}</p></div>`)}<div class="asset-summary-links"><button data-asset-tab="documents">${icon('file')}<span><b>${requirements.length} itens na lista documental</b><small>${requirements.filter(r=>requirementStatus(a.state,r,a.NOW).tone!=='green').length} precisam de conferência</small></span>${icon('chevron')}</button><button data-asset-tab="finance">${icon('wallet')}<span><b>Obrigações e movimentações</b><small>Contrato, valor e documentos de origem</small></span>${icon('chevron')}</button><button data-asset-tab="tasks">${icon('task')}<span><b>${tasks.filter(t=>!t.done).length} próximas ações</b><small>Diretas e relacionadas aos documentos</small></span>${icon('chevron')}</button></div></div></div>${panel('Contratos relacionados','As regras e condições permanecem em cada contrato.',a.scope('contracts').filter(c=>c.asset===x.id).map(c=>link(c.title,'contract',c.id,c.party+' · '+c.number,'contract')).join('')||empty('Sem contrato relacionado','O ativo pode existir antes de um contrato.'))}`}`;
  }
  function docList(docs){return `<div class="asset-document-list">${docs.map(d=>`<button class="profile-document" data-open="document" data-id="${esc(d.id)}"><span class="profile-document-icon">${icon('file')}</span><span><b>${esc(d.name)}</b><small>${esc(d.type)} · ${fullDate(d.date)}</small></span>${pill(d.status,d.status==='Revisado'?'green':'amber')}${icon('chevron')}</button>`).join('')||empty('Nenhum documento nesta categoria','Vincule um documento do acervo ou envie um arquivo.')}</div>`}
  function assetDocumentation(x){return `<div class="profile-section-title"><div><h2>Documentação esperada</h2><p>Defina o que este ativo precisa ter e qual documento atende a cada item.</p></div>${btn('Adicionar item',`data-open="asset-requirement" data-id="${esc(x.id)}"`,'','plus')}</div><section class="panel requirement-list">${x.dossier.requirements.map(r=>{const s=requirementStatus(a.state,r,a.NOW),d=owned('documents',r.doc);return `<article class="requirement-row"><div class="requirement-check ${s.tone}">${icon(s.tone==='green'?'check':'file')}</div><div><h3>${esc(r.title)}</h3>${d?`<button class="textbtn" data-open="document" data-id="${esc(d.id)}">${esc(d.name)} ${icon('chevron')}</button>`:'<p>Documento ainda não vinculado</p>'}${r.validUntil?`<small>Validade informada: ${fullDate(r.validUntil)}</small>`:''}${r.note?`<small>${esc(r.note)}</small>`:''}</div>${pill(s.label,s.tone)}${btn('Editar',`data-open="asset-requirement" data-id="${esc(x.id)}" data-requirement="${esc(r.id)}"`)}</article>`}).join('')||empty('Monte a lista deste ativo','Ex.: identificação, comprovação do vínculo, licença, apólice ou manual. Adapte à sua necessidade.')}</section><div class="profile-section-title"><div><h2>Documentos relacionados</h2><p>Documentação cadastral e documentos das operações ficam separados.</p></div><div class="profile-document-actions">${btn('Vincular do acervo',`data-open="asset-link-document" data-id="${esc(x.id)}"`,'','link')}${btn('Enviar documento',`data-open="newdoc" data-id="asset:${esc(x.id)}"`,'primary','plus')}</div></div><div class="asset-doc-columns">${panel('Documentação do ativo','Identificação, vínculo, licenças e referências permanentes.',docList(assetDocuments(a.state,x,'documentation')))}${panel('Documentos das operações','Cobranças, faturas e comprovantes, com seu contexto de origem.',docList(assetDocuments(a.state,x,'support')))}</div><p class="reference-footnote">Conferência documental, prazo informado e pagamento são controles independentes. A lista é organizacional e não certifica regularidade do ativo.</p>`}
  function assetFinance(x){const obs=assetObligations(a.state,x).filter(o=>o.competence===a.month),ids=new Set(obs.map(o=>o.id)),tx=a.scope('transactions').filter(t=>ids.has(t.obligation));return `<div class="profile-section-title"><div><h2>Obrigações e movimentos do ativo</h2><p>Competência selecionada; cada obrigação abre sua composição e realização.</p></div>${a.monthSelect()}</div><div class="asset-finance-stats">${a.stat('Recebido',money(tx.filter(t=>t.amount>0).reduce((v,t)=>v+t.amount,0)),'Das obrigações selecionadas','in')}${a.stat('Pago',money(-tx.filter(t=>t.amount<0).reduce((v,t)=>v+t.amount,0)),'Das obrigações selecionadas','out')}${a.stat('Saldo das obrigações',money(obs.reduce((v,o)=>v+remaining(a.state,o),0)),'A pagar e a receber, sem compensar','wallet')}</div>${panel('Origem de cada valor','Previsto e realizado mantêm suas datas e classificações.',`<div class="table-wrap"><table><thead><tr><th>Vencimento</th><th>Obrigação / contraparte</th><th>Direção</th><th class="money">Previsto</th><th class="money">Realizado</th><th></th></tr></thead><tbody>${obs.map(o=>`<tr><td>${fullDate(o.due)}</td><td><button class="textbtn" data-open="obligation" data-id="${esc(o.id)}">${esc(o.title)}</button><small>${esc(o.party)}</small></td><td>${o.kind==='in'?'A receber':'A pagar'}</td><td class="money">${money(total(o))}</td><td class="money">${money(a.paid(a.state,o))}</td><td>${pill(a.status(o).label,a.status(o).tone)}</td></tr>`).join('')}</tbody></table></div>${!obs.length?empty('Nenhuma obrigação nesta competência','Escolha outro mês ou cadastre uma obrigação relacionada.'):''}`)}${panel('Movimentos relacionados','Datas efetivas de pagamento e recebimento das obrigações acima.',tx.length?a.transactionTable([...tx].sort((u,v)=>u.date.localeCompare(v.date))):empty('Nenhum movimento realizado','As obrigações previstas continuam independentes.'))}`}
  function assetTaskList(x){return `<div class="profile-section-title"><div><h2>Próximas ações</h2><p>Tarefas do ativo, dos contratos, das obrigações e dos documentos relacionados.</p></div>${btn('Criar tarefa',`data-open="newtask" data-id="asset:${esc(x.id)}"`,'primary','plus')}</div><section class="panel task-list">${assetTasks(a.state,x).sort((u,v)=>u.due.localeCompare(v.due)).map(t=>`<div class="taskrow ${t.done?'completed':''}"><button class="check ${t.done?'done':''}" data-toggle-task="${esc(t.id)}" aria-label="${t.done?'Reabrir':'Concluir'} tarefa: ${esc(t.title)}">${t.done?icon('check'):''}</button><div class="task-title"><button data-open="task" data-id="${esc(t.id)}">${esc(t.title)}</button><small>${fullDate(t.due)} · ${esc(t.owner)}</small></div>${pill(t.done?'Concluída':'A fazer',t.done?'green':'')}</div>`).join('')||empty('Nenhuma tarefa relacionada','Crie uma próxima ação com o contexto deste ativo.')}</section>`}
  function options(type,selected=''){return `<option value="">Selecione</option>${a.scope(type).map(x=>`<option value="${esc(x.id)}" ${selected===x.id?'selected':''}>${esc((x.name||x.title)+(type==='obligations'?' · '+x.competence:''))}</option>`).join('')}`}
  function purposeOptions(selected='documentation'){return Object.entries(PURPOSES).map(([id,label])=>`<option value="${id}" ${id===selected?'selected':''}>${label}</option>`).join('')}
  function refForm(d){const kind=a.current.refKind||'asset';return {heading:'Documento · referências',wide:true,body:`<h2>${esc(d.name)}</h2><p class="description">${esc(d.type)} · ${fullDate(d.date)}</p>`+referencePanel(d,false)+a.formShell('Acrescentar uma referência','Identifique o assunto e o papel deste documento. Vínculos existentes serão preservados.',`<label>Referente a<select name="kind" data-reference-kind>${Object.entries(ENTITY_TYPES).map(([id,label])=>`<option value="${id}" ${kind===id?'selected':''}>${label}</option>`).join('')}</select></label><label>Qual ${kind==='company'?'empresa':kind==='asset'?'ativo':kind==='contract'?'contrato':'obrigação'}?<select name="entity" required>${kind==='company'?`<option value="${esc(a.company)}">${esc(a.get('companies',a.company).name)}</option>`:options(COLLECTIONS[kind])}</select></label><label>Finalidade<select name="purpose">${kind==='obligation'?'<option value="support">Documento da operação</option>':purposeOptions(documentReferences(a.state,d).some(r=>r.purpose==='support')?'support':'documentation')}</select></label><label>O que este documento representa aqui?<textarea name="note" maxlength="500" placeholder="Ex.: comprova a propriedade; fundamenta o rateio; recibo desta parcela."></textarea></label><div class="form-error" role="alert"></div>`,'document-reference',d.id,'Acrescentar referência')+`${d.references?.length?`<div class="drawer-section"><h3>Referências acrescentadas manualmente</h3>${d.references.map((r,i)=>`<div class="manual-reference"><span>${esc(entity(a.state,r.kind,r.id,a.company)?.name||entity(a.state,r.kind,r.id,a.company)?.title||'Referência indisponível')}<small>${esc(PURPOSES[r.purpose])}</small></span>${btn('Desvincular',`data-remove-reference="${esc(d.id)}" data-reference-index="${i}"`)}</div>`).join('')}<p class="annotation">Desvincular remove apenas esta referência manual. O arquivo e os vínculos de origem permanecem no acervo.</p></div>`:''}`}}
  function assetForm(id){const x=owned('assets',id),draft=a.current.assetDraft??={name:x?.name||'',kind:x?.kind||'Imóvel',relationship:x?.relationship||'Propriedade',status:x?.status||'Cadastrado',description:x?.description||'',details:x?.details||'',fields:structuredClone(x?.dossier.attributes||assetFields('Imóvel'))};
    return {heading:x?'Ativo · editar características':'Cadastrar ativo',wide:true,body:a.formShell(x?'Características do ativo':'Um ativo com contexto','Use os campos do tipo escolhido e acrescente as particularidades que sua operação precisa.',`<label>Nome do ativo<input name="name" maxlength="100" required value="${esc(draft.name)}" placeholder="Ex.: Sala 302"></label><div class="formrow"><label>Tipo de ativo<select name="kind" data-asset-model>${Object.keys(ATTRIBUTE_MODELS).map(k=>`<option ${draft.kind===k?'selected':''}>${k}</option>`).join('')}</select></label><label>Situação<input name="status" maxlength="70" value="${esc(draft.status)}" required></label></div><label>Relação com a empresa<select name="relationship">${['Propriedade','Locação','Administração','Propriedade financiada','Outro'].map(k=>`<option ${draft.relationship===k?'selected':''}>${k}</option>`).join('')}</select></label><label>Descrição / localização<input name="description" maxlength="180" value="${esc(draft.description)}"></label><div class="attribute-editor"><div class="reference-heading"><h3>Campos deste ativo</h3>${btn('Adicionar campo','data-add-asset-field','','plus')}</div><p>Ao trocar o tipo, seus campos preenchidos são mantidos.</p>${draft.fields.map((f,i)=>`<div class="attribute-row"><label>Característica ${i+1}<input name="fieldLabel" maxlength="80" value="${esc(f.label)}" required></label><label>Valor<input name="fieldValue" maxlength="250" value="${esc(f.value)}" placeholder="A informar"></label><button type="button" class="iconbtn" data-remove-asset-field="${i}" aria-label="Remover característica ${i+1}">${icon('close')}</button></div>`).join('')}</div><label>Contexto e particularidades<textarea name="details" maxlength="1600" placeholder="Uso, responsabilidades, regras de conferência ou condições específicas.">${esc(draft.details)}</textarea></label><div class="form-error" role="alert"></div>`,'asset-edit',id||'','Salvar ativo')};
  }
  function dialog(kind,id){sync();
    if(kind==='asset'){const x=owned('assets',id);return {heading:'Dossiê do ativo',wide:true,body:x?profile(x,true):empty('Ativo indisponível','Selecione um ativo desta empresa.')}}
    if(kind==='newasset'||kind==='asset-edit')return assetForm(id);
    if(kind==='document-references'){const d=owned('documents',id);return d?refForm(d):null}
    if(kind==='asset-link-document'){const x=owned('assets',id);return {heading:'Ativo · vincular documento',body:a.formShell('Vincular documento a '+esc(x.name),'O mesmo original pode atender a mais de um ativo ou operação.',`<label>Documento do acervo<select name="document" required>${options('documents')}</select></label><label>Finalidade<select name="purpose">${purposeOptions()}</select></label><label>Referência / contexto<textarea name="note" maxlength="500"></textarea></label>`,'asset-link-document',id,'Vincular documento')}}
    if(kind==='asset-requirement'){const x=owned('assets',id),r=x.dossier.requirements.find(r=>r.id===a.current.requirement)||{};return {heading:'Ativo · documentação esperada',body:a.formShell(r.id?'Editar item documental':'Adicionar item documental','Defina a necessidade e associe o documento que a atende. A conferência do arquivo continua independente.',`<input type="hidden" name="requirement" value="${esc(r.id||'')}"><label>Documento ou evidência esperada<input name="title" maxlength="140" required value="${esc(r.title||'')}" placeholder="Ex.: matrícula, apólice, licença ou manual"></label><label>Documento que atende este item<select name="document">${options('documents',r.doc)}</select></label><label>Validade / prazo informado (opcional)<input type="date" name="validUntil" value="${esc(r.validUntil||'')}"></label><label>Orientação para conferência<textarea name="note" maxlength="600">${esc(r.note||'')}</textarea></label>`,'asset-requirement',id,'Salvar item')}}
    return null;
  }
  function captureAsset(){const form=document.querySelector('form[data-form="asset-edit"]');if(!form)return;const data=new FormData(form),draft=a.current.assetDraft;for(const key of ['name','kind','relationship','status','description','details'])draft[key]=String(data.get(key)||'');const values=data.getAll('fieldValue');draft.fields=data.getAll('fieldLabel').map((label,i)=>({label:String(label),value:String(values[i]||'')}))}
  function click(d){
    if(d.assetPage){setAsset(d.assetPage);a.navigate('assets/'+encodeURIComponent(d.assetPage));return true}
    if(d.assetsList!==undefined){activeAsset='';a.navigate('assets');return true}
    if(d.assetTab){assetTab=d.assetTab;if(a.current?.kind==='asset')a.draw();else a.render();return true}
    if(d.inventoryKind){assetKind=d.inventoryKind;a.render();return true}
    if(d.referenceFilter){docContext=d.referenceFilter;a.render();return true}
    if(d.inventoryView){docView=d.inventoryView;a.render();return true}
    if(d.requirement){a.open('asset-requirement',d.id);a.current.requirement=d.requirement;a.draw();return true}
    if(d.addAssetField!==undefined){captureAsset();a.current.assetDraft.fields.push({label:'',value:''});a.draw();return true}
    if(d.removeAssetField!==undefined){captureAsset();a.current.assetDraft.fields.splice(Number(d.removeAssetField),1);a.draw();return true}
    if(d.removeReference){const doc=owned('documents',d.removeReference);if(doc){doc.references.splice(Number(d.referenceIndex),1);a.save();a.render();a.draw();a.toast('Referência manual removida; original e demais vínculos preservados.')}return true}
    return false;
  }
  function change(e){const d=e.target.dataset;
    if(d.inventorySearch!==undefined){docSearch=e.target.value;a.render();return true}
    if(d.inventoryState!==undefined){docState=e.target.value;a.render();return true}
    if(d.referenceKind!==undefined){a.current.refKind=e.target.value;a.draw();return true}
    if(d.assetModel!==undefined){const previous=a.current.assetDraft.kind;captureAsset();const draft=a.current.assetDraft;draft.fields=adaptAssetFields(draft.fields,draft.kind,previous);a.draw();return true}
    return false;
  }
  function submit(form,data){const kind=form.dataset.form,id=form.dataset.id,v=k=>String(data.get(k)||'').trim();
    if(kind==='asset-edit'){const labels=data.getAll('fieldLabel').map(x=>String(x).trim()),values=data.getAll('fieldValue').map(x=>String(x).trim());if(new Set(labels.map(x=>x.toLowerCase())).size!==labels.length){form.querySelector('.form-error').textContent='Use nomes diferentes para as características.';return true}let x=owned('assets',id);if(!x){x={id:uid('asset'),company:a.company,dossier:{attributes:[],requirements:[]}};a.state.assets.push(x)}for(const key of ['name','kind','relationship','status','description','details'])x[key]=v(key);x.dossier.attributes=labels.map((label,i)=>({label,value:values[i]}));a.save();setAsset(x.id);a.navigate('assets/'+encodeURIComponent(x.id));a.toast('Características salvas; documentos e movimentações preservados.');return true}
    if(kind==='document-reference'){const d=owned('documents',id);try{addReference(a.state,d,{kind:v('kind'),id:v('entity'),purpose:v('purpose'),note:v('note')});a.save();a.render();a.draw();a.toast('Referência acrescentada ao mesmo documento.')}catch(error){form.querySelector('.form-error').textContent=error.message}return true}
    if(kind==='asset-link-document'){const x=owned('assets',id),d=owned('documents',v('document'));if(!x||!d)return true;addReference(a.state,d,{kind:'asset',id:x.id,purpose:v('purpose'),note:v('note')});a.save();setAsset(x.id);assetTab='documents';a.navigate('assets/'+encodeURIComponent(x.id));assetTab='documents';a.render();a.toast('Documento relacionado ao ativo sem duplicar o original.');return true}
    if(kind==='asset-requirement'){const x=owned('assets',id),doc=owned('documents',v('document'));if(!x)return true;let r=x.dossier.requirements.find(r=>r.id===v('requirement'));if(!r){r={id:uid('requirement')};x.dossier.requirements.push(r)}Object.assign(r,{title:v('title'),doc:doc?.id||'',validUntil:v('validUntil'),note:v('note')});if(doc)addReference(a.state,doc,{kind:'asset',id:x.id,purpose:'documentation',note:'Relacionado à lista documental do ativo.'});a.save();setAsset(x.id);a.navigate('assets/'+encodeURIComponent(x.id));assetTab='documents';a.render();a.toast('Item documental salvo. Confira o conteúdo do documento associado.');return true}
    return false;
  }
  return {documents,inventory,dialog,click,change,submit,setAsset,referencePanel,goAsset(id){setAsset(id);a.navigate('assets/'+encodeURIComponent(id))}};
}
